package org.apache.commons.cli;

import java.io.*;
import java.io.PrintWriter;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.Iterator;
import java.util.List;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class HelpFormatter_findWrapPos_TriageGen2Test {

    @Test
    public void testFindWrapPos_NoWrap() {
        HelpFormatter helpFormatter = new HelpFormatter();
        String text = "HelloWorld";
        int width = 5;
        int startPos = 0;
        int result = helpFormatter.findWrapPos(text, width, startPos);
        assertEquals(5, result);
    }

    @Test
    public void testFindWrapPos_WrapAtSpace() {
        HelpFormatter helpFormatter = new HelpFormatter();
        String text = "Hello World";
        int width = 5;
        int startPos = 0;
        int result = helpFormatter.findWrapPos(text, width, startPos);
        assertEquals(6, result);
    }

    @Test
    public void testFindWrapPos_WrapAtTab() {
        HelpFormatter helpFormatter = new HelpFormatter();
        String text = "Hello\tWorld";
        int width = 5;
        int startPos = 0;
        int result = helpFormatter.findWrapPos(text, width, startPos);
        assertEquals(6, result);
    }

    @Test
    public void testFindWrapPos_WrapAtNewLine() {
        HelpFormatter helpFormatter = new HelpFormatter();
        String text = "Hello\nWorld";
        int width = 5;
        int startPos = 0;
        int result = helpFormatter.findWrapPos(text, width, startPos);
        assertEquals(6, result);
    }

    @Test
    public void testFindWrapPos_NewLineBeforeWidth() {
        HelpFormatter helpFormatter = new HelpFormatter();
        String text = "Hello\nWorld";
        int width = 10;
        int startPos = 0;
        int result = helpFormatter.findWrapPos(text, width, startPos);
        assertEquals(6, result);
    }

    @Test
    public void testFindWrapPos_TabBeforeWidth() {
        HelpFormatter helpFormatter = new HelpFormatter();
        String text = "Hello\tWorld";
        int width = 10;
        int startPos = 0;
        int result = helpFormatter.findWrapPos(text, width, startPos);
        assertEquals(6, result);
    }

    @Test
    public void testFindWrapPos_NoWrapAtEnd() {
        HelpFormatter helpFormatter = new HelpFormatter();
        String text = "Hello World";
        int width = 10;
        int startPos = 10;
        int result = helpFormatter.findWrapPos(text, width, startPos);
        assertEquals(-1, result);
    }

    @Test
    public void testFindWrapPos_NullText() {
        HelpFormatter helpFormatter = new HelpFormatter();
        String text = null;
        int width = 10;
        int startPos = 0;
        int result = helpFormatter.findWrapPos(text, width, startPos);
        assertNull(result);
    }

    @Test
    public void testFindWrapPos_EmptyText() {
        HelpFormatter helpFormatter = new HelpFormatter();
        String text = "";
        int width = 10;
        int startPos = 0;
        int result = helpFormatter.findWrapPos(text, width, startPos);
        assertEquals(0, result);
    }

    @Test
    public void testFindWrapPos_TextTooLong() {
        HelpFormatter helpFormatter = new HelpFormatter();
        String text = "Hello World";
        int width = 10;
        int startPos = 0;
        int result = helpFormatter.findWrapPos(text, width, startPos);
        assertEquals(10, result);
    }

    @Test
    public void testFindWrapPos_StartPosTooBig() {
        HelpFormatter helpFormatter = new HelpFormatter();
        String text = "Hello World";
        int width = 10;
        int startPos = 20;
        int result = helpFormatter.findWrapPos(text, width, startPos);
        assertEquals(-1, result);
    }

    @Test
    public void testFindWrapPos_WidthTooBig() {
        HelpFormatter helpFormatter = new HelpFormatter();
        String text = "Hello World";
        int width = 100;
        int startPos = 0;
        int result = helpFormatter.findWrapPos(text, width, startPos);
        assertEquals(11, result);
    }

}
